import React, { useState, useEffect } from "react";
import { useParams } from "react-router-dom";
import "./DetailsProduct.scss";

const DetailsProduct = () => {
  const { productId } = useParams();
  const [product, setProduct] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchProduct = async () => {
      try {
        const response = await fetch("/products.json");

        if (!response.ok) {
          throw new Error("Erro ao carregar os produtos");
        }

        const data = await response.json();

        const selectedProduct = data.find((p) => String(p.referenceId) === String(productId));
        setProduct(selectedProduct);
      } catch (error) {
        console.error("Erro ao carregar o produto:", error);
      } finally {
        setLoading(false);
      }
    };

    fetchProduct();
  }, [productId]);

  if (loading) return <p>Carregando...</p>;
  if (!product) return <p>Produto não encontrado.</p>;

  return (
    <div className="details-product">
      <div className="product-gallery">
        {product.images && product.images.length > 0 ? (
          product.images.map((image, index) => (
            <img key={index} src={image.imageUrl} alt={image.imageText || `Produto ${index + 1}`} />
          ))
        ) : (
          <img src="/no-image.jpg" alt="Imagem não disponível" />
        )}
      </div>

      <div className="product-info">
        <h1>{product.productName}</h1>
        <p className="description">{product.metaTagDescription || "Sem descrição"}</p>
        <p className="price">
          {product.installments}x de R$ {product.priceParcelado ? product.priceParcelado.toFixed(2) : "Preço indisponível"}
        </p>
        <button className="add-to-cart">ADICIONAR À SACOLA</button>
      </div>
    </div>
  );
};

export default DetailsProduct;
